// Original CODE X STOCKS artwork (generated by scripts/art/generate-art.mjs).
// These are illustrations, never photos of a real account, and the UI labels them as such.
// Vite imports an image as a URL string; Next.js imports it as { src, width, height }.
import heroWide from "../assets/art/hero-dusk-2560.webp";
import heroMid from "../assets/art/hero-dusk-1440.webp";
import heroPortrait from "../assets/art/hero-dusk-portrait.webp";
import sceneDawn from "../assets/art/scene-dawn.webp";
import sceneDesert from "../assets/art/scene-desert.webp";
import sceneSnow from "../assets/art/scene-snow.webp";
import sceneStorm from "../assets/art/scene-storm.webp";
import cardDusk from "../assets/art/card-dusk.webp";
import cardDawn from "../assets/art/card-dawn.webp";
import cardDesert from "../assets/art/card-desert.webp";
import cardSnow from "../assets/art/card-snow.webp";
import cardStorm from "../assets/art/card-storm.webp";
import loginDusk from "../assets/art/login-dusk.webp";
import loginSnow from "../assets/art/login-snow.webp";

export function assetUrl(mod: unknown): string {
  if (typeof mod === "string") return mod;
  if (mod && typeof mod === "object" && "src" in mod) return String((mod as { src: string }).src);
  return "";
}

export const ART = {
  heroWide: assetUrl(heroWide),
  heroMid: assetUrl(heroMid),
  heroPortrait: assetUrl(heroPortrait),
  dawn: assetUrl(sceneDawn),
  desert: assetUrl(sceneDesert),
  snow: assetUrl(sceneSnow),
  storm: assetUrl(sceneStorm),
  loginDusk: assetUrl(loginDusk),
  loginSnow: assetUrl(loginSnow),
};

export const ART_ALT = {
  hero: "Illustration: transport plane and parachutes drifting over misty hills at dusk",
  dawn: "Illustration: suspension bridge over a misty bay at dawn",
  desert: "Illustration: desert mesas and a dusty road in late-afternoon haze",
  snow: "Illustration: snowy mountains under the northern lights at night",
  storm: "Illustration: a glowing blue zone wall sweeping across a stormy valley",
};

const CARDS = [cardDusk, cardDawn, cardDesert, cardSnow, cardStorm].map(assetUrl);

/**
 * Decorative artwork for an item that has no photo of its own. In a list, pass the position so
 * neighbours never repeat; on its own, the id picks a stable scene.
 */
export function fallbackArt(id: string, index?: number): string {
  if (index !== undefined) return CARDS[index % CARDS.length];
  let h = 2166136261;
  for (let i = 0; i < id.length; i++) h = Math.imul(h ^ id.charCodeAt(i), 16777619) >>> 0;
  return CARDS[h % CARDS.length];
}
